mapper.select:
SELECT id, user_id, module, action, operation_type, operation_result, timestamp, details, ip_address
FROM audit_log
WHERE id = #{id}

SELECT id, user_id, module, action, operation_type, operation_result, timestamp, details, ip_address
FROM audit_log
WHERE user_id = #{userId}
ORDER BY timestamp DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM audit_log
WHERE user_id = #{userId}

SELECT id, user_id, module, action, operation_type, operation_result, timestamp, details, ip_address
FROM audit_log
WHERE timestamp BETWEEN #{startTime} AND #{endTime}
ORDER BY timestamp DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM audit_log
WHERE timestamp BETWEEN #{startTime} AND #{endTime}

SELECT id, user_id, module, action, operation_type, operation_result, timestamp, details, ip_address
FROM audit_log
WHERE 1=1

    AND user_id = #{userId}


    AND module = #{module}


    AND action = #{action}


    AND operation_type = #{operationType}


    AND timestamp BETWEEN #{startTime} AND #{endTime}

ORDER BY timestamp DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM audit_log
WHERE 1=1

    AND user_id = #{userId}


    AND module = #{module}


    AND action = #{action}


    AND operation_type = #{operationType}


    AND timestamp BETWEEN #{startTime} AND #{endTime}
